"""Deterministic Mira copy for languages supported by onboarding.

Business names, place names and scheme identifiers are interpolated as supplied;
the surrounding instructions never silently fall back to English.
"""

SUPPORTED = frozenset({"en", "hi", "mr", "te", "ta", "kn"})
SCRIPT_RANGES = {"hi": (0x0900, 0x097F), "mr": (0x0900, 0x097F),
                 "te": (0x0C00, 0x0C7F), "ta": (0x0B80, 0x0BFF),
                 "kn": (0x0C80, 0x0CFF)}


def has_selected_script(text: str, language: str) -> bool:
    """Reject an LLM answer wholly in another language before speaking it."""
    bounds = SCRIPT_RANGES.get(language)
    if not bounds:
        return True
    letters = sum(char.isalpha() for char in text)
    selected = sum(bounds[0] <= ord(char) <= bounds[1] for char in text)
    return selected >= max(3, int(letters * 0.2))


